#pragma once

#include <cstdint>
#include <deque>
#include <functional>
#include <string>
#include <string_view>

// Lines generated by the AI server, spoken through the engine's regular AI_Output path.
// The engine asks for text/duration via Gothic::externalMessageFn; the first request means
// the npc starts speaking the line.
class LineLibrary final {
  public:
    struct Line final {
      std::string id;
      std::string npc;   // script symbol of the speaker
      std::string text;  // game codepage
      uint32_t    time    = 0;
      bool        started = false;
      };

    static bool isExternal(std::string_view id) { return id.starts_with("AIB_"); }
    static uint32_t durationFor(std::string_view text);

    void        add(std::string id, std::string npc, std::string text);
    bool        lookup(std::string_view id, std::string_view& text, uint32_t& time);
    void        clear() { lines.clear(); }

    std::function<void(const Line&)> onStart;

  private:
    static constexpr size_t MaxLines = 256;
    std::deque<Line> lines;
  };
